(507, 'page_scroll_to_id_instances', 'a:1:{s:17:\"mPS2id_instance_0\";a:35:{s:8:\"selector\";a:10:{s:5:\"value\";s:28:\"a[href*=\'#\']:not([href=\'#\'])\";s:6:\"values\";N;s:2:\"id\";s:28:\"page_scroll_to_id_0_selector\";s:10:\"field_type\";s:4:\"text\";s:5:\"label\";s:11:\"Selector(s)\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:663:\"Set the links (in the form of <a href=\"https://www.w3.org/TR/css3-selectors/\" target=\"_blank\">CSS selectors</a>) that will scroll the page when clicked (default value: any link with a non-empty hash (<code>#</code>) value in its URL) <br /><small>In addition to selectors above, the plugin is enabled automatically on links (or links contained within elements) with class <code>ps2id</code></small> <br /><small><a class=\"button button-small mPS2id-show-option-common-values\" href=\"#\">Show common values</a><span>For all links: <code>a[href*=\'#\']:not([href=\'#\'])</code><br />For menu links only: <code>.menu-item a[href*=\'#\']:not([href=\'#\'])</code></span></small>\";s:7:\"wrapper\";N;}s:21:\"autoSelectorMenuLinks\";a:10:{s:5:\"value\";s:4:\"true\";s:6:\"values\";N;s:2:\"id\";s:41:\"page_scroll_to_id_0_autoSelectorMenuLinks\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:30:\"Enable on WordPress Menu links\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:185:\"Automatically enable the plugin on custom links (containing <code>#</code> in their URL) created in Appearance &rarr; Menus <br /><small>Requires WordPress version 3.6 or higher</small>\";s:7:\"wrapper\";s:8:\"fieldset\";}s:15:\"excludeSelector\";a:10:{s:5:\"value\";s:166:\"a[href^=\'#tab-\'], a[href^=\'#tabs-\'], a[data-toggle]:not([data-toggle=\'tooltip\']), a[data-slide], a[data-vc-tabs], a[data-vc-accordion], a.screen-reader-text.skip-link\";s:6:\"values\";N;s:2:\"id\";s:35:\"page_scroll_to_id_0_excludeSelector\";s:10:\"field_type\";s:4:\"text\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";s:22:\"selectors are excluded\";s:11:\"description\";s:513:\"Set the links (in the form of <a href=\"https://www.w3.org/TR/css3-selectors/\" target=\"_blank\">CSS selectors</a>) that will be excluded from plugin&apos;s selectors (the plugin will not hanlde these links) <br /><small><a class=\"button button-small mPS2id-show-option-common-values\" href=\"#\">Show common values</a><span><code>a[href^=\'#tab-\'], a[href^=\'#tabs-\'], a[data-toggle]:not([data-toggle=\'tooltip\']), a[data-slide], a[data-vc-tabs], a[data-vc-accordion], a.screen-reader-text.skip-link</code></span></small>\";s:7:\"wrapper\";N;}s:11:\"scrollSpeed\";a:10:{s:5:\"value\";i:800;s:6:\"values\";N;s:2:\"id\";s:31:\"page_scroll_to_id_0_scrollSpeed\";s:10:\"field_type\";s:12:\"text-integer\";s:5:\"label\";s:15:\"Scroll duration\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";s:12:\"milliseconds\";s:11:\"description\";s:99:\"Scroll animation duration (i.e. scrolling speed) in milliseconds (1000 milliseconds equal 1 second)\";s:7:\"wrapper\";N;}s:15:\"autoScrollSpeed\";a:10:{s:5:\"value\";s:4:\"true\";s:6:\"values\";N;s:2:\"id\";s:35:\"page_scroll_to_id_0_autoScrollSpeed\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:30:\"Auto-adjust scrolling duration\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:104:\"Enable to let the plugin fine-tune scrolling duration/speed according to target and page scroll position\";s:7:\"wrapper\";s:8:\"fieldset\";}s:12:\"scrollEasing\";a:10:{s:5:\"value\";s:14:\"easeInOutQuint\";s:6:\"values\";s:406:\"linear,swing,easeInQuad,easeOutQuad,easeInOutQuad,easeInCubic,easeOutCubic,easeInOutCubic,easeInQuart,easeOutQuart,easeInOutQuart,easeInQuint,easeOutQuint,easeInOutQuint,easeInExpo,easeOutExpo,easeInOutExpo,easeInSine,easeOutSine,easeInOutSine,easeInCirc,easeOutCirc,easeInOutCirc,easeInElastic,easeOutElastic,easeInOutElastic,easeInBack,easeOutBack,easeInOutBack,easeInBounce,easeOutBounce,easeInOutBounce\";s:2:\"id\";s:32:\"page_scroll_to_id_0_scrollEasing\";s:10:\"field_type\";s:6:\"select\";s:5:\"label\";s:18:\"Scroll type/easing\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:192:\"Scroll animation easing (<a href=\"http://manos.malihu.gr/page-scroll-to-id-for-wordpress/#ps2id-duration-easings-demo\" target=\"_blank\">visual representation &amp; demo of all easing types</a>)\";s:7:\"wrapper\";N;}s:15:\"scrollingEasing\";a:10:{s:5:\"value\";s:12:\"easeOutQuint\";s:6:\"values\";s:406:\"linear,swing,easeInQuad,easeOutQuad,easeInOutQuad,easeInCubic,easeOutCubic,easeInOutCubic,easeInQuart,easeOutQuart,easeInOutQuart,easeInQuint,easeOutQuint,easeInOutQuint,easeInExpo,easeOutExpo,easeInOutExpo,easeInSine,easeOutSine,easeInOutSine,easeInCirc,easeOutCirc,easeInOutCirc,easeInElastic,easeOutElastic,easeInOutElastic,easeInBack,easeOutBack,easeInOutBack,easeInBounce,easeOutBounce,easeInOutBounce\";s:2:\"id\";s:35:\"page_scroll_to_id_0_scrollingEasing\";s:10:\"field_type\";s:6:\"select\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:98:\"Alternative animation easing (applied when a link is clicked while the page is animated/scrolling)\";s:7:\"wrapper\";N;}s:17:\"forceScrollEasing\";a:10:{s:5:\"value\";s:5:\"false\";s:6:\"values\";N;s:2:\"id\";s:37:\"page_scroll_to_id_0_forceScrollEasing\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:24:\"Force scroll type/easing\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:132:\"Enable if the selected animation easing does not seem to take effect and/or there\'s conflict with other easing libraries and plugins\";s:7:\"wrapper\";s:8:\"fieldset\";}s:19:\"pageEndSmoothScroll\";a:10:{s:5:\"value\";s:4:\"true\";s:6:\"values\";N;s:2:\"id\";s:39:\"page_scroll_to_id_0_pageEndSmoothScroll\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:15:\"Scroll behavior\";s:14:\"checkbox_label\";s:65:\"Always scroll smoothly when reaching the end of the page/document\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";N;s:7:\"wrapper\";s:8:\"fieldset\";}s:22:\"stopScrollOnUserAction\";a:10:{s:5:\"value\";s:5:\"false\";s:6:\"values\";N;s:2:\"id\";s:42:\"page_scroll_to_id_0_stopScrollOnUserAction\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:49:\"Stop page scrolling on mouse-wheel or touch-swipe\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:127:\"Enable if you want to stop page scrolling when the user tries to scroll the page manually (e.g. via mouse-wheel or touch-swipe)\";s:7:\"wrapper\";s:8:\"fieldset\";}s:17:\"autoCorrectScroll\";a:10:{s:5:\"value\";s:5:\"false\";s:6:\"values\";N;s:2:\"id\";s:37:\"page_scroll_to_id_0_autoCorrectScroll\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:99:\"Verify target position and readjust scrolling (if necessary), after scrolling animation is complete\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";N;s:7:\"wrapper\";s:8:\"fieldset\";}s:23:\"autoCorrectScrollExtend\";a:10:{s:5:\"value\";s:5:\"false\";s:6:\"values\";N;s:2:\"id\";s:43:\"page_scroll_to_id_0_autoCorrectScrollExtend\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:138:\"Extend target position verification and scrolling adjustment for lazy-load scripts (images, iframes etc.) and changes in document\'s length\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";N;s:7:\"wrapper\";s:8:\"fieldset\";}s:6:\"layout\";a:10:{s:5:\"value\";s:8:\"vertical\";s:6:\"values\";s:24:\"vertical,horizontal,auto\";s:2:\"id\";s:26:\"page_scroll_to_id_0_layout\";s:10:\"field_type\";s:5:\"radio\";s:5:\"label\";s:11:\"Page layout\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";s:24:\"vertical|horizontal|auto\";s:10:\"field_info\";N;s:11:\"description\";s:346:\"Restrict page scrolling to top-bottom (vertical) or left-right (horizontal) accordingly. For both vertical and horizontal scrolling select <code>auto</code> <br /><small>Please note that \"Layout\" option does not transform your theme&#8217;s templates layout (i.e. it won&#8217;t change your theme/page design from vertical to horizontal).</small>\";s:7:\"wrapper\";s:8:\"fieldset\";}s:6:\"offset\";a:10:{s:5:\"value\";s:3:\"100\";s:6:\"values\";N;s:2:\"id\";s:26:\"page_scroll_to_id_0_offset\";s:10:\"field_type\";s:4:\"text\";s:5:\"label\";s:6:\"Offset\";s:14:\"checkbox_label\";N;s:12:\"radio_labels\";N;s:10:\"field_info\";s:6:\"pixels\";s:11:\"description\";s:190:\"Offset scroll-to position by x amount of pixels (positive or negative) or by <a href=\"https://www.w3.org/TR/css3-selectors/\" target=\"_blank\">selector</a> (e.g. <code>#navigation-menu</code>)\";s:7:\"wrapper\";N;}s:11:\"dummyOffset\";a:10:{s:5:\"value\";s:5:\"false\";s:6:\"values\";N;s:2:\"id\";s:31:\"page_scroll_to_id_0_dummyOffset\";s:10:\"field_type\";s:8:\"checkbox\";s:5:\"label\";s:0:\"\";s:14:\"checkbox_label\";s:54:\"Auto-generate <code>#ps2id-dummy-offset</code> element\";s:12:\"radio_labels\";N;s:10:\"field_info\";N;s:11:\"description\";s:393:\"Enable if you want the plugin to create a hidden element and use its selector as offset. The element that will be created is: <code>#ps2id-dummy-offset</code> <br /><small>You should use the <code>#ps2id-dummy-offset</code> value in the <b>Offset</b> option above. You should then use the same selector/value and in your CSS and give it a height equal to the amount of offset you want.</small>\";s:7:\"wrapper\";s:8:\"fieldset\";}s:17:\"highlightSelector\";a:10:{s:5:\"value\";s:0:\"\";s:6:\"values\";N;s:2:\"id\";s:37:\"page_scroll_to_id_0_highlightSelector\";s:10:\"field_type\";s:4:\"text\";s:5:\"label\";s:21:\"Highlight selector(s)\";s:14:\"checkbox_label\";N;s:12:\"r