(7, 8, '_form', '<div class=\"bg\">\n<div class=\"row\">\n<div class=\"col-lg-6 col-md-6 col-12\">\n<label>Nom :</label>\n[text* nom class:form-control]\n</div>\n<div class=\"col-lg-6 col-md-6 col-12\">\n<label>Courriel :</label>\n[email* courriel class:form-control]\n</div>\n<div class=\"col-lg-6 col-md-6 col-12\">\n<label>Téléphone :</label>\n[tel* phone class:form-control]\n</div>\n<div class=\"col-lg-6 col-md-6 col-12\">\n<label>Adresse :</label>\n[text address class:form-control]\n</div>\n<div class=\"col-lg-12 col-md-12 col-12\">\n<label>Message:</label>\n[textarea message class:form-control]\n</div>\n<div class=\"col-lg-12 text-end col-md-12 col-12\">\n<button class=\"btn-default\" type=\"submit\">Envoyer</button>\n</div>\n</div>\n</div>'),
(8, 8, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:18:\"Demande de contact\";s:6:\"sender\";s:46:\"[_site_title] <siteweb@sonicproelectricite.ca>\";s:9:\"recipient\";s:31:\"sonic.pro.electricite@gmail.com\";s:4:\"body\";s:225:\"Nom: [nom]  <br>\nCourriel: [courriel] <br>\nTéléphone: [phone] <br>\nAdresse: [address] <br>\nMessage: [message] <br>\n\n <br>\n-- \n <br>\nCe courriel a été envoyé à partir d\'un formulaire de contact sur [_site_title] ([_url])\";s:18:\"additional_headers\";s:20:\"Reply-To: [courriel]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:1;s:13:\"exclude_blank\";b:0;}'),
(9, 8, '_mail_2', 'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:43:\"[_site_title] <wordpress@wecreatedesign.co>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:220:\"Message Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(10, 8, '_messages', 'a:22:{s:12:\"mail_sent_ok\";s:45:\"Thank you for your message. It has been sent.\";s:12:\"mail_sent_ng\";s:71:\"There was an error trying to send your message. Please try again later.\";s:16:\"validation_error\";s:61:\"One or more fields have an error. Please check and try again.\";s:4:\"spam\";s:71:\"There was an error trying to send your message. Please try again later.\";s:12:\"accept_terms\";s:69:\"You must accept the terms and conditions before sending your message.\";s:16:\"invalid_required\";s:27:\"Please fill out this field.\";s:16:\"invalid_too_long\";s:32:\"This field has a too long input.\";s:17:\"invalid_too_short\";s:33:\"This field has a too short input.\";s:13:\"upload_failed\";s:46:\"There was an unknown error uploading the file.\";s:24:\"upload_file_type_invalid\";s:49:\"You are not allowed to upload files of this type.\";s:21:\"upload_file_too_large\";s:31:\"The uploaded file is too large.\";s:23:\"upload_failed_php_error\";s:38:\"There was an error uploading the file.\";s:12:\"invalid_date\";s:41:\"Please enter a date in YYYY-MM-DD format.\";s:14:\"date_too_early\";s:32:\"This field has a too early date.\";s:13:\"date_too_late\";s:31:\"This field has a too late date.\";s:14:\"invalid_number\";s:22:\"Please enter a number.\";s:16:\"number_too_small\";s:34:\"This field has a too small number.\";s:16:\"number_too_large\";s:34:\"This field has a too large number.\";s:23:\"quiz_answer_not_correct\";s:36:\"The answer to the quiz is incorrect.\";s:13:\"invalid_email\";s:30:\"Please enter an email address.\";s:11:\"invalid_url\";s:19:\"Please enter a URL.\";s:11:\"invalid_tel\";s:32:\"Please enter a telephone number.\";}'),
