(1235, 355, '_advantages_0_image', 'field_679c625ce244f'),
(1236, 355, 'advantages_0_title', 'L’avantage Sonic-Pro Électricité inc.'),
(1237, 355, '_advantages_0_title', 'field_679c6267e2450'),
(1238, 355, 'advantages_0_accordian_points_0_title', 'Souci du travail bien fait'),
(1239, 355, '_advantages_0_accordian_points_0_title', 'field_679c6292e2452'),
(1240, 355, 'advantages_0_accordian_points_0_content', 'Chaque projet est exécuté avec une attention méticuleuse aux détails, pour des résultats de haute qualité.'),
(1241, 355, '_advantages_0_accordian_points_0_content', 'field_679c6299e2453'),
(1242, 355, 'advantages_0_accordian_points_1_title', 'Honnêteté'),
(1243, 355, '_advantages_0_accordian_points_1_title', 'field_679c6292e2452'),
(1244, 355, 'advantages_0_accordian_points_1_content', 'Nous garantissons une transparence totale, vous offrant une communication claire et des tarifs justes.'),
(1245, 355, '_advantages_0_accordian_points_1_content', 'field_679c6299e2453'),
(1246, 355, 'advantages_0_accordian_points_2_title', 'Professionnalisme'),
(1247, 355, '_advantages_0_accordian_points_2_title', 'field_679c6292e2452'),
(1248, 355, 'advantages_0_accordian_points_2_content', 'Notre équipe est hautement qualifiée et respectueuse des normes les plus élevées du secteur.'),
(1249, 355, '_advantages_0_accordian_points_2_content', 'field_679c6299e2453'),
(1250, 355, 'advantages_0_accordian_points_3_title', 'Ponctualité'),
(1251, 355, '_advantages_0_accordian_points_3_title', 'field_679c6292e2452'),
(1252, 355, 'advantages_0_accordian_points_3_content', 'Notre engagement envers vos échéances est ferme, assurant ainsi l\'achèvement de votre projet dans les temps convenus.'),
(1253, 355, '_advantages_0_accordian_points_3_content', 'field_679c6299e2453'),
(1254, 355, 'advantages_0_accordian_points_4_title', 'Rapidité'),
(1255, 355, '_advantages_0_accordian_points_4_title', 'field_679c6292e2452'),
(1256, 355, 'advantages_0_accordian_points_4_content', 'Nos réponses et interventions sont rapides, minimisant les désagréments et accélérant la réalisation des travaux.'),
(1257, 355, '_advantages_0_accordian_points_4_content', 'field_679c6299e2453'),
(1258, 355, 'advantages_0_accordian_points', '5'),
(1259, 355, '_advantages_0_accordian_points', 'field_679c6287e2451'),
