(2187, 19, '_services_0_image', 'field_679c64edcdc49'),
(2188, 19, 'services_0_title', 'Essai électrique, basse et moyenne tension'),
(2189, 19, '_services_0_title', 'field_679c6429605b2'),
(2190, 19, 'services_0_content', 'Assurez la longévité et la performance de vos installations électriques tout en minimisant les risques de panne imprévue. Grâce à l\'essai électrique, basse ou moyenne tension, vous réduirez vos besoins de maintenance et bénéficierez de l\'assurance d\'une installation fiable qui soutient vos activités quotidiennes.'),
(2191, 19, '_services_0_content', 'field_679c6504cdc4a'),
(2192, 19, 'services_1_image', '394'),
(2193, 19, '_services_1_image', 'field_679c64edcdc49'),
(2194, 19, 'services_1_title', 'Vérification pré-opérationnelle'),
(2195, 19, '_services_1_title', 'field_679c6429605b2'),
(2196, 19, 'services_1_content', 'Faites confiance à nos experts pour prévenir les incidents et assurer une performance optimale dès le départ, vous épargnant ainsi du temps, de l\'argent et des soucis inutiles. En détectant les problèmes avant qu\'ils ne surviennent, cette étape cruciale garantit la fiabilité et la sécurité de vos installations dès leur mise en service.'),
(2197, 19, '_services_1_content', 'field_679c6504cdc4a'),
(2198, 19, 'services_2_image', '375'),
