(2574, 408, 'advantages_0_accordian_points_0_title', 'Souci du travail bien fait'),
(2575, 408, '_advantages_0_accordian_points_0_title', 'field_679c6292e2452'),
(2576, 408, 'advantages_0_accordian_points_0_content', 'Chaque projet est exécuté avec une attention méticuleuse aux détails, pour des résultats de haute qualité.'),
(2577, 408, '_advantages_0_accordian_points_0_content', 'field_679c6299e2453'),
(2578, 408, 'advantages_0_accordian_points_1_title', 'Honnêteté'),
(2579, 408, '_advantages_0_accordian_points_1_title', 'field_679c6292e2452'),
(2580, 408, 'advantages_0_accordian_points_1_content', 'Nous garantissons une transparence totale, vous offrant une communication claire et des tarifs justes.'),
(2581, 408, '_advantages_0_accordian_points_1_content', 'field_679c6299e2453'),
(2582, 408, 'advantages_0_accordian_points_2_title', 'Professionnalisme'),
(2583, 408, '_advantages_0_accordian_points_2_title', 'field_679c6292e2452'),
(2584, 408, 'advantages_0_accordian_points_2_content', 'Notre équipe est hautement qualifiée et respectueuse des normes les plus élevées du secteur.'),
