(2586, 408, 'advantages_0_accordian_points_3_title', 'Ponctualité'),
(2587, 408, '_advantages_0_accordian_points_3_title', 'field_679c6292e2452'),
(2588, 408, 'advantages_0_accordian_points_3_content', 'Notre engagement envers vos échéances est ferme, assurant ainsi l\'achèvement de votre projet dans les temps convenus.'),
