(2591, 408, '_advantages_0_accordian_points_4_title', 'field_679c6292e2452'),
(2592, 408, 'advantages_0_accordian_points_4_content', 'Nos réponses et interventions sont rapides, minimisant les désagréments et accélérant la réalisation des travaux.'),
