(2635, 410, '_banner_0_icon', 'field_679c5af7bdc69'),
(2636, 410, 'banner_0_title', 'Service d\'<span>électricien professionnel</span> à Repentigny'),
(2637, 410, '_banner_0_title', 'field_679c5aecbdc68'),
(2638, 410, 'banner_0_sub_title', 'L\'électricité, une question de confiance'),
(2639, 410, '_banner_0_sub_title', 'field_679c5b13bdc6a'),
(2640, 410, 'banner_0_content', 'Avec près de 10 ans d\'expérience, Sonic-Pro Électricité inc. combine l\'expertise théorique et la pratique pour résoudre vos problèmes électriques avec efficacité.\r\n<p data-aos=\"fade-left\" data-aos-delay=\"200\">Que ce soit pour une simple installation de prises ou la complexité d’une construction neuve, nous sommes votre solution!</p>'),
