(2961, 410, '_advantages_0_accordian_points_3_title', 'field_679c6292e2452'),
(2962, 410, 'advantages_0_accordian_points_3_content', 'Notre engagement envers vos échéances est ferme, assurant ainsi l\'achèvement de votre projet dans les temps convenus.'),
