(3318, 411, 'advantages_0_title', 'L’<span>avantage</span> Sonic-Pro Électricité inc'),
(3319, 411, '_advantages_0_title', 'field_679c6267e2450'),
(3320, 411, 'advantages_0_accordian_points_0_title', 'Souci du travail bien fait'),
(3321, 411, '_advantages_0_accordian_points_0_title', 'field_679c6292e2452'),
(3322, 411, 'advantages_0_accordian_points_0_content', 'Chaque projet est exécuté avec une attention méticuleuse aux détails, pour des résultats de haute qualité.'),
(3323, 411, '_advantages_0_accordian_points_0_content', 'field_679c6299e2453'),
(3324, 411, 'advantages_0_accordian_points_1_title', 'Honnêteté'),
(3325, 411, '_advantages_0_accordian_points_1_title', 'field_679c6292e2452'),
(3326, 411, 'advantages_0_accordian_points_1_content', 'Nous garantissons une transparence totale, vous offrant une communication claire et des tarifs justes.'),
(3327, 411, '_advantages_0_accordian_points_1_content', 'field_679c6299e2453'),
(3328, 411, 'advantages_0_accordian_points_2_title', 'Professionnalisme'),
(3329, 411, '_advantages_0_accordian_points_2_title', 'field_679c6292e2452'),
(3330, 411, 'advantages_0_accordian_points_2_content', 'Notre équipe est hautement qualifiée et respectueuse des normes les plus élevées du secteur.'),
(3331, 411, '_advantages_0_accordian_points_2_content', 'field_679c6299e2453'),
(3332, 411, 'advantages_0_accordian_points_3_title', 'Ponctualité'),
(3333, 411, '_advantages_0_accordian_points_3_title', 'field_679c6292e2452'),
(3334, 411, 'advantages_0_accordian_points_3_content', 'Notre engagement envers vos échéances est ferme, assurant ainsi l\'achèvement de votre projet dans les temps convenus.'),
(3335, 411, '_advantages_0_accordian_points_3_content', 'field_679c6299e2453'),
(3336, 411, 'advantages_0_accordian_points_4_title', 'Rapidité'),
(3337, 411, '_advantages_0_accordian_points_4_title', 'field_679c6292e2452'),
(3338, 411, 'advantages_0_accordian_points_4_content', 'Nos réponses et interventions sont rapides, minimisant les désagréments et accélérant la réalisation des travaux.'),
(3339, 411, '_advantages_0_accordian_points_4_content', 'field_679c6299e2453'),
(3340, 411, 'advantages_0_accordian_points', '5'),
(3341, 411, '_advantages_0_accordian_points', 'field_679c6287e2451'),
(3342, 411, 'advantages', '1'),
(3343, 411, '_advantages', 'field_679c6248e244e'),
(3344, 411, 'full_with_content_0_title', ' Des solutions électriques sur mesure'),
(3345, 411, '_full_with_content_0_title', 'field_679c62e0a7f0e'),
(3346, 411, 'full_with_content_0_content', 'Chez Sonic-Pro Électricité inc., notre priorité est de vous fournir des services électriques fiables et sécurisés. Que ce soit pour une nouvelle construction, une rénovation ou un dépannage, nous avons la solution. Confiez-nous vos projets électriques, et nous nous engageons à illuminer votre quotidien!'),
