(4572, 441, 'advantages_0_accordian_points_0_title', 'Souci du travail bien fait'),
(4573, 441, '_advantages_0_accordian_points_0_title', 'field_679c6292e2452'),
(4574, 441, 'advantages_0_accordian_points_0_content', 'Chaque projet est exécuté avec une attention méticuleuse aux détails, pour des résultats de haute qualité.'),
(4575, 441, '_advantages_0_accordian_points_0_content', 'field_679c6299e2453'),
(4576, 441, 'advantages_0_accordian_points_1_title', 'Honnêteté'),
(4577, 441, '_advantages_0_accordian_points_1_title', 'field_679c6292e2452'),
(4578, 441, 'advantages_0_accordian_points_1_content', 'Nous garantissons une transparence totale, vous offrant une communication claire et des tarifs justes.'),
(4579, 441, '_advantages_0_accordian_points_1_content', 'field_679c6299e2453'),
(4580, 441, 'advantages_0_accordian_points_2_title', 'Professionnalisme'),
(4581, 441, '_advantages_0_accordian_points_2_title', 'field_679c6292e2452'),
(4582, 441, 'advantages_0_accordian_points_2_content', 'Notre équipe est hautement qualifiée et respectueuse des normes les plus élevées du secteur.'),
(4583, 441, '_advantages_0_accordian_points_2_content', 'field_679c6299e2453'),
(4584, 441, 'advantages_0_accordian_points_3_title', 'Ponctualité'),
(4585, 441, '_advantages_0_accordian_points_3_title', 'field_679c6292e2452'),
(4586, 441, 'advantages_0_accordian_points_3_content', 'Notre engagement envers vos échéances est ferme, assurant ainsi l\'achèvement de votre projet dans les temps convenus.'),
(4587, 441, '_advantages_0_accordian_points_3_content', 'field_679c6299e2453'),
(4588, 441, 'advantages_0_accordian_points_4_title', 'Rapidité'),
(4589, 441, '_advantages_0_accordian_points_4_title', 'field_679c6292e2452'),
(4590, 441, 'advantages_0_accordian_points_4_content', 'Nos réponses et interventions sont rapides, minimisant les désagréments et accélérant la réalisation des travaux.'),
(4591, 441, '_advantages_0_accordian_points_4_content', 'field_679c6299e2453'),
