(4595, 441, '_advantages', 'field_679c6248e244e'),
(4596, 441, 'full_with_content_0_title', ' Des solutions électriques sur mesure'),
(4597, 441, '_full_with_content_0_title', 'field_679c62e0a7f0e'),
(4598, 441, 'full_with_content_0_content', 'Chez Sonic-Pro Électricité inc., notre priorité est de vous fournir des services électriques fiables et sécurisés. Que ce soit pour une nouvelle construction, une rénovation ou un dépannage, nous avons la solution. Confiez-nous vos projets électriques, et nous nous engageons à illuminer votre quotidien!'),
(4599, 441, '_full_with_content_0_content', 'field_679c62eaa7f0f');
