(4944, 442, 'advantages_0_accordian_points_0_title', 'Souci du travail bien fait'),
(4945, 442, '_advantages_0_accordian_points_0_title', 'field_679c6292e2452'),
(4946, 442, 'advantages_0_accordian_points_0_content', 'Chaque projet est exécuté avec une attention méticuleuse aux détails, pour des résultats de haute qualité.'),
