(5350, 461, '_advantages_0_image', 'field_679c625ce244f'),
(5351, 461, 'advantages_0_title', 'L’<span>avantage</span> Sonic-Pro Électricité inc'),
(5352, 461, '_advantages_0_title', 'field_679c6267e2450'),
(5353, 461, 'advantages_0_accordian_points_0_title', 'Souci du travail bien fait'),
(5354, 461, '_advantages_0_accordian_points_0_title', 'field_679c6292e2452'),
(5355, 461, 'advantages_0_accordian_points_0_content', 'Chaque projet est exécuté avec une attention méticuleuse aux détails, pour des résultats de haute qualité.'),
(5356, 461, '_advantages_0_accordian_points_0_content', 'field_679c6299e2453'),
(5357, 461, 'advantages_0_accordian_points_1_title', 'Honnêteté'),
(5358, 461, '_advantages_0_accordian_points_1_title', 'field_679c6292e2452'),
(5359, 461, 'advantages_0_accordian_points_1_content', 'Nous garantissons une transparence totale, vous offrant une communication claire et des tarifs justes.'),
(5360, 461, '_advantages_0_accordian_points_1_content', 'field_679c6299e2453'),
(5361, 461, 'advantages_0_accordian_points_2_title', 'Professionnalisme'),
(5362, 461, '_advantages_0_accordian_points_2_title', 'field_679c6292e2452'),
(5363, 461, 'advantages_0_accordian_points_2_content', 'Notre équipe est hautement qualifiée et respectueuse des normes les plus élevées du secteur.'),
(5364, 461, '_advantages_0_accordian_points_2_content', 'field_679c6299e2453'),
(5365, 461, 'advantages_0_accordian_points_3_title', 'Ponctualité'),
(5366, 461, '_advantages_0_accordian_points_3_title', 'field_679c6292e2452'),
(5367, 461, 'advantages_0_accordian_points_3_content', 'Notre engagement envers vos échéances est ferme, assurant ainsi l\'achèvement de votre projet dans les temps convenus.'),
(5368, 461, '_advantages_0_accordian_points_3_content', 'field_679c6299e2453'),
(5369, 461, 'advantages_0_accordian_points_4_title', 'Rapidité'),
(5370, 461, '_advantages_0_accordian_points_4_title', 'field_679c6292e2452'),
(5371, 461, 'advantages_0_accordian_points_4_content', 'Nos réponses et interventions sont rapides, minimisant les désagréments et accélérant la réalisation des travaux.'),
(5372, 461, '_advantages_0_accordian_points_4_content', 'field_679c6299e2453'),
(5373, 461, 'advantages_0_accordian_points', '5'),
(5374, 461, '_advantages_0_accordian_points', 'field_679c6287e2451'),
(5375, 461, 'advantages', '1'),
(5376, 461, '_advantages', 'field_679c6248e244e'),
(5377, 461, 'full_with_content_0_title', ' Des solutions électriques sur mesure'),
(5378, 461, '_full_with_content_0_title', 'field_679c62e0a7f0e'),
(5379, 461, 'full_with_content_0_content', 'Chez Sonic-Pro Électricité inc., notre priorité est de vous fournir des services électriques fiables et sécurisés. Que ce soit pour une nouvelle construction, une rénovation ou un dépannage, nous avons la solution. Confiez-nous vos projets électriques, et nous nous engageons à illuminer votre quotidien!'),
